#include <stdio.h>

int main(void) {
    int n = 5, sum = 0;
    long fact = 1;
    for (int i = 1; i <= n; i++) { sum += i; fact *= i; }
    printf("sum=%d fact=%ld\n", sum, fact);
    for (int i = 1; i <= 3; i++) printf("%d x %d = %d\n", n, i, n * i);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n = 12321, rev = 0, sum = 0;
    for (int t = n; t > 0; t /= 10) { rev = rev * 10 + t % 10; sum += t % 10; }
    printf("rev=%d sum=%d palindrome=%s\n", rev, sum, rev == n ? "yes" : "no");
    int p = 97, prime = 1;
    for (int d = 2; d * d <= p; d++) if (p % d == 0) { prime = 0; break; }
    printf("prime=%s\n", prime ? "yes" : "no");
    return 0;
}

