lab.solution:
#include <stdio.h>

int main(void) {
    int n; scanf("%d", &n);
    int t = n, rev = 0, sum = 0;
    while (t > 0) { rev = rev * 10 + t % 10; sum += t % 10; t /= 10; }
    printf("reverse=%d sum=%d palindrome=%s\n", rev, sum, rev == n ? "yes" : "no");
    return 0;
}
